28	// nctxProvider wraps the NCtx lookup; *monitor.Hub satisfies this interface.
29	type nctxProvider interface {
30		NCtx(model string) int
31	}
32	
33	// processManager is the subset of process.Manager the Gateway depends on.
34	type processManager interface {
35		Loaded(name string) bool
36		// LoadOrGet returns a ticket for the named model, loading it on demand if
37		// not already running. The caller waits on ticket.Ready() for the backend
38		// address and must call ticket.Release() when the request completes.
39		LoadOrGet(modelName string, params config.ModelParams) *process.LoadTicket
40		// ListModels returns all known models in non-idle states.
41		ListModels() []monitor.ModelInfo
42	}
43	
44	// hfCache caches HF model IDs with a TTL to avoid repeated filesystem I/O.
45	type hfCache struct {
46		mu    sync.Mutex
47		ids   []string
48		until time.Time
49	}
50	
51	func (c *hfCache) get(ttl time.Duration) ([]string, bool) {
52		c.mu.Lock()
53		defer c.mu.Unlock()
54		if time.Now().Before(c.until) {
55			return c.ids, true
56		}
57		return nil, false
58	}
59	
60	func (c *hfCache) set(ids []string, ttl time.Duration) {
61		c.mu.Lock()
62		defer c.mu.Unlock()
63		c.ids = ids
64		c.until = time.Now().Add(ttl)
65	}
