67	// Gateway is an HTTP reverse-proxy that routes OpenAI-compatible requests to llama-server processes.
68	type Gateway struct {
69		cfg        atomic.Pointer[config.Config]
70		mgr        processManager
71		q          *queue.Queue
72		log        *slog.Logger
73		affinity   *affinityTable
74		hub        nctxProvider
75		remote     *monitor.RemoteTracker
76		discovery  *monitor.ModelDiscovery
77		server     *http.Server
78		hfCacheDir string  // HuggingFace hub cache directory; empty disables scanning
79		hfCache    hfCache // cached HF model IDs
80	}
81	
82	// New creates a Gateway backed by the given process manager.
83	// hub may be nil; when non-nil, /monitor and /monitor/ws routes are registered.
84	// remote may be nil; when non-nil, remote provider requests are tracked.
85	func New(cfg *config.Config, mgr *process.Manager, hub *monitor.Hub, remote *monitor.RemoteTracker, discovery *monitor.ModelDiscovery, log *slog.Logger) *Gateway {
86		g := newGateway(cfg, mgr, hub, remote, discovery, log)
87		if home, err := os.UserHomeDir(); err == nil {
88			g.hfCacheDir = filepath.Join(home, ".cache", "huggingface", "hub")
89		}
90		return g
91	}
92	
93	func newGateway(cfg *config.Config, mgr processManager, hub *monitor.Hub, remote *monitor.RemoteTracker, discovery *monitor.ModelDiscovery, log *slog.Logger) *Gateway {
94		// Build affinity table from warmup models.
95		modelSlots := make(map[string]int, len(cfg.Warmup))
96		for _, name := range cfg.Warmup {
97			if params, ok := cfg.MatchModel(name); ok {
98				modelSlots[name] = params.Slots
99			}
100		}
101	
102		g := &Gateway{mgr: mgr, log: log, affinity: newAffinityTable(modelSlots), remote: remote, discovery: discovery}
103		g.cfg.Store(cfg)
104	
105		qDepth := cfg.QueueDepth
106		if qDepth <= 0 {
107			qDepth = 200
108		}
109		g.q = queue.New(qDepth, func(ctx context.Context, model string) (string, func(), error) {
110			params, ok := g.cfg.Load().MatchModel(model)
111			if !ok {
112				return "", nil, fmt.Errorf("unknown model: %s", model)
113			}
114			t := g.mgr.LoadOrGet(model, params)
115			select {
116			case addr, ok := <-t.Ready():
117				if !ok {
118					return "", nil, t.Err()
119				}
120				return addr, t.Release, nil
121			case <-ctx.Done():
122				// Drain in background so the manager's in-flight counter stays consistent.
123				go func() {
124					if _, ok := <-t.Ready(); ok {
125						t.Release()
126					}
127				}()
128				return "", nil, ctx.Err()
129			}
130		})
131	
132		// Store hub as nctxProvider nil-safely: a nil *monitor.Hub must not become
133		// a non-nil interface value, which would cause g.hub == nil checks to fail.
134		if hub != nil {
135			g.hub = hub
136		}
137	
138		mux := http.NewServeMux()
139		mux.HandleFunc("POST /v1/chat/completions", g.handleRoute)
140		mux.HandleFunc("POST /v1/completions", g.handleRoute)
141		mux.HandleFunc("POST /v1/embeddings", g.handleRoute)
142		mux.HandleFunc("POST /v1/rerank", g.handleRoute)
143		mux.HandleFunc("GET /v1/models", g.handleModels)
144		mux.HandleFunc("GET /health", g.handleHealth)
145	
146		if hub != nil {
147			mux.HandleFunc("GET /monitor", monitor.HandlePage)
148			mux.HandleFunc("GET /monitor/ws", monitor.HandleWS(hub))
149		}
150	
151		g.server = &http.Server{Addr: cfg.Listen, Handler: mux}
152		return g
153	}
154	
155	// ListenAndServe starts the HTTP server and shuts it down when ctx is cancelled.
156	func (g *Gateway) ListenAndServe(ctx context.Context) error {
157		errCh := make(chan error, 1)
158		go func() {
159			if err := g.server.ListenAndServe(); err != nil && err != http.ErrServerClosed {
160				errCh <- err
161			}
162		}()
163		select {
164		case err := <-errCh:
165			return err
166		case <-ctx.Done():
167			shutCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
168			defer cancel()
169			return g.server.Shutdown(shutCtx)
170		}
171	}
