179	// handleRoute extracts the model field from the JSON body and proxies to the matching process.
180	// If the model is known but not loaded, it is started on demand; the HTTP connection
181	// is held open until the model becomes healthy.
182	func (g *Gateway) handleRoute(w http.ResponseWriter, r *http.Request) {
183		// Read body once for all operations: model extraction, token estimation, slot affinity.
184		allBody, err := io.ReadAll(r.Body)
185		if err != nil {
186			writeError(w, http.StatusBadRequest, "invalid_request_error", "failed to read body", "bad_request")
187			return
188		}
189	
190		var payload struct {
191			Model string `json:"model"`
192		}
193		if err := json.Unmarshal(allBody, &payload); err != nil {
194			writeError(w, http.StatusBadRequest, "invalid_request_error", "invalid JSON: "+err.Error(), "bad_request")
195			return
196		}
197		if payload.Model == "" {
198			writeError(w, http.StatusBadRequest, "invalid_request_error", "missing model field", "bad_request")
199			return
200		}
201	
202		currentCfg := g.cfg.Load()
203		params, ok := currentCfg.MatchModel(payload.Model)
204		var snap monitor.DiscoverySnapshot
205		if !ok && g.discovery != nil {
206			snap = g.discovery.Snapshot()
207			if dm, found := snap.Lookup(payload.Model); found {
208				if _, provOk := currentCfg.Providers[dm.Provider]; provOk {
209					params = config.ModelParams{Provider: dm.Provider}
210					ok = true
211				}
212			}
213		}
214		if !ok {
215			writeError(w, http.StatusNotFound, "invalid_request_error", "unknown model: "+payload.Model, "model_not_found")
216			return
217		}
218	
219		if params.IsRemote() {
220			g.handleRemote(w, r, payload.Model, params, currentCfg, allBody)
221			return // handleRemote handles body rewrite if needed
222		}
223	
224		prio := pathPriority(r.URL.Path)
225		ticket := g.q.Enqueue(payload.Model, prio, r.Context())
226		var addr string
227		select {
228		case a, ok := <-ticket.Ready():
229			if !ok {
230				err := ticket.Err()
231				switch {
232				case errors.Is(err, queue.ErrQueueFull):
233					w.Header().Set("Retry-After", "5")
234					writeError(w, http.StatusServiceUnavailable, "server_error", "queue at capacity", "queue_full")
235				case errors.Is(err, queue.ErrModelEvicted), errors.Is(err, process.ErrModelDraining):
236					w.Header().Set("Retry-After", "10")
237					writeError(w, http.StatusServiceUnavailable, "server_error", "model unavailable, retry later", "model_draining")
238				case errors.Is(err, context.DeadlineExceeded):
239					writeError(w, http.StatusGatewayTimeout, "server_error", "model load timed out", "load_timeout")
240				default:
241					writeError(w, http.StatusServiceUnavailable, "server_error", err.Error(), "model_not_loaded")
242				}
243				return
244			}
245			addr = a
246		case <-r.Context().Done():
247			writeError(w, http.StatusServiceUnavailable, "server_error", "request cancelled", "request_cancelled")
248			return
249		}
250		defer ticket.Release()
251	
252		if g.hub != nil {
253			if nCtx := g.hub.NCtx(payload.Model); nCtx > 0 {
254				if est := estimateTokens(allBody); est > 0 && est > nCtx*9/10 {
255					writeError(w, http.StatusBadRequest, "invalid_request_error",
256						fmt.Sprintf("estimated %d tokens exceeds context window of %d (n_ctx)", est, nCtx),
257						"context_length_exceeded")
258					return
259				}
260			}
261		}
262	
263		g.affinity.Register(payload.Model, params.Slots)
264	
265		hash := prefixHash(allBody)
266		if slotID, assigned := g.affinity.Assign(payload.Model, hash); assigned {
267			allBody = injectSlot(allBody, slotID)
268		}
269		r.Body = io.NopCloser(bytes.NewReader(allBody))
270		r.ContentLength = int64(len(allBody))
271	
272		target, parseErr := url.Parse(addr)
273		if parseErr != nil {
274			writeError(w, http.StatusInternalServerError, "server_error", "invalid backend URL", "internal_error")
275			return
276		}
277	
278		proxy := &httputil.ReverseProxy{
279			Rewrite: func(pr *httputil.ProxyRequest) {
280				pr.SetURL(target)
281				pr.Out.Host = target.Host
282			},
283			FlushInterval:  -1,
284			ModifyResponse: rewriteContextLengthError,
285			ErrorHandler: func(w http.ResponseWriter, _ *http.Request, err error) {
286				g.log.Error("proxy error", "model", payload.Model, "error", err)
287				writeError(w, http.StatusBadGateway, "server_error", "upstream error: "+err.Error(), "upstream_error")
288			},
289		}
290	
291		proxy.ServeHTTP(w, r)
292	}
