294	// handleModels returns all known models with their current status.
295	func (g *Gateway) handleModels(w http.ResponseWriter, _ *http.Request) {
296		type modelObj struct {
297			ID           string   `json:"id"`
298			Object       string   `json:"object"`
299			Type         string   `json:"type"`
300			Status       string   `json:"status,omitempty"`
301			Capabilities []string `json:"capabilities,omitempty"`
302			Provider     string   `json:"provider,omitempty"`
303		}
304		type modelsResp struct {
305			Object string     `json:"object"`
306			Data   []modelObj `json:"data"`
307		}
308	
309		models := g.Models()
310		data := make([]modelObj, 0, len(models))
311		for _, m := range models {
312			data = append(data, modelObj{
313				ID:           m.ID,
314				Object:       m.Object,
315				Type:         m.Type,
316				Status:       m.Status,
317				Capabilities: m.Capabilities,
318				Provider:     m.Provider,
319			})
320		}
321	
322		w.Header().Set("Content-Type", "application/json")
323		json.NewEncoder(w).Encode(modelsResp{Object: "list", Data: data}) //nolint:errcheck
324	}
325	
326	// Models returns all known models as ModelInfo slice.
327	func (g *Gateway) Models() []monitor.ModelInfo {
328		cfg := g.cfg.Load()
329		var models []monitor.ModelInfo
330	
331		// Local models from Manager (loaded/running)
332		localModels := g.mgr.ListModels()
333		for _, mi := range localModels {
334			obj := monitor.ModelInfo{
335				ID:     mi.ID,
336				Object: "model",
337				Type:   "local",
338				Status: mi.Status,
339			}
340			if p, ok := cfg.MatchModel(mi.ID); ok {
341				obj.Capabilities = p.Capabilities
342			}
343			models = append(models, obj)
344		}
345	
346		listed := make(map[string]bool, len(models))
347		for _, m := range models {
348			listed[m.ID] = true
349		}
350	
351		// HF cache models (local but not loaded)
352		for _, cm := range g.scanHFCache() {
353			if listed[cm] {
354				continue
355			}
356			models = append(models, monitor.ModelInfo{
357				ID:     cm,
358				Object: "model",
359				Type:   "local",
360				Status: "available",
361			})
362			listed[cm] = true
363		}
364	
365		// Configured remote models
366		configuredRemote := make(map[string]bool)
367		for pattern, p := range cfg.Models {
368			if !p.IsRemote() {
369				continue
370			}
371			configuredRemote[pattern] = true
372			models = append(models, monitor.ModelInfo{
373				ID:           pattern,
374				Object:       "model",
375				Type:         "remote",
376				Status:       "available",
377				Capabilities: p.Capabilities,
378				Provider:     p.Provider,
379			})
380		}
381	
382		// Discovered remote models
383		if g.discovery != nil {
384			for _, dm := range g.discovery.Snapshot().AllModels() {
385				if configuredRemote[dm.ID] {
386					continue
387				}
388				models = append(models, monitor.ModelInfo{
389					ID:       dm.ID,
390					Object:   "model",
391					Type:     "remote",
392					Status:   "available",
393					Provider: dm.Provider,
394				})
395			}
396		}
397	
398		return models
399	}
