401	// handleHealth returns 200 if at least one warmup model is healthy, 503 otherwise.
402	func (g *Gateway) handleHealth(w http.ResponseWriter, _ *http.Request) {
403		w.Header().Set("Content-Type", "application/json")
404		if slices.ContainsFunc(g.cfg.Load().Warmup, g.mgr.Loaded) {
405			w.WriteHeader(http.StatusOK)
406			json.NewEncoder(w).Encode(map[string]string{"status": "ok"}) //nolint:errcheck
407			return
408		}
409		w.WriteHeader(http.StatusServiceUnavailable)
410		json.NewEncoder(w).Encode(map[string]string{"status": "degraded"}) //nolint:errcheck
411	}
