413	// handleRemote proxies a request to a remote OpenAI-compatible provider,
414	// bypassing the process manager entirely. body may be rewound if upstream_model rewrite is needed.
415	func (g *Gateway) handleRemote(w http.ResponseWriter, r *http.Request, modelName string, params config.ModelParams, cfg *config.Config, body []byte) {
416		provider, ok := cfg.Providers[params.Provider]
417		if !ok {
418			writeError(w, http.StatusInternalServerError, "server_error", "unknown provider: "+params.Provider, "config_error")
419			return
420		}
421	
422		if params.UpstreamModel != "" {
423			var obj map[string]json.RawMessage
424			if err := json.Unmarshal(body, &obj); err == nil {
425				if raw, err := json.Marshal(params.UpstreamModel); err == nil {
426					obj["model"] = raw
427					if rewritten, err := json.Marshal(obj); err == nil {
428						body = rewritten
429					}
430				}
431			}
432		}
433		r.Body = io.NopCloser(bytes.NewReader(body))
434		r.ContentLength = int64(len(body))
435	
436		baseTarget, err := url.Parse(provider.BaseURL)
437		if err != nil {
438			writeError(w, http.StatusInternalServerError, "server_error", "invalid provider URL", "config_error")
439			return
440		}
441	
442		apiKey := provider.APIKey
443		reqPath := r.URL.Path
444		upstreamModel := params.UpstreamModel
445		if upstreamModel == "" {
446			upstreamModel = modelName
447		}
448	
449		// Track remote request metrics.
450		var done func(int64, int)
451		if g.remote != nil {
452			done = g.remote.Start(modelName, params.Provider)
453		}
454		start := time.Now()
455	
456		proxy := &httputil.ReverseProxy{
457			Rewrite: func(pr *httputil.ProxyRequest) {
458				pr.SetURL(baseTarget)
459				pr.Out.URL.Path = baseTarget.Path + reqPath
460				pr.Out.Host = baseTarget.Host
461				pr.Out.Header.Set("Authorization", "Bearer "+apiKey)
462			},
463			FlushInterval: -1,
464			ModifyResponse: func(resp *http.Response) error {
465				resp.Header.Set("X-Wire-Model", upstreamModel)
466				if done != nil {
467					done(time.Since(start).Nanoseconds(), resp.StatusCode)
468					done = nil // prevent double-call
469				}
470				return rewriteContextLengthError(resp)
471			},
472			ErrorHandler: func(w http.ResponseWriter, _ *http.Request, err error) {
473				g.log.Error("remote proxy error", "model", modelName, "provider", params.Provider, "error", err)
474				if done != nil {
475					done(time.Since(start).Nanoseconds(), 502)
476					done = nil
477				}
478				writeError(w, http.StatusBadGateway, "server_error", "upstream error: "+err.Error(), "upstream_error")
479			},
480		}
481	
482		proxy.ServeHTTP(w, r)
483	}
