485	// estimateTokens approximates the token count of a request body using a
486	// chars/4 heuristic. It extracts text from messages[].content (chat) and the
487	// input field (embeddings). Returns 0 on parse failure or empty content.
488	func estimateTokens(body []byte) int {
489		var req struct {
490			Messages []struct {
491				Content json.RawMessage `json:"content"`
492			} `json:"messages"`
493			Input json.RawMessage `json:"input"`
494		}
495		if err := json.Unmarshal(body, &req); err != nil {
496			return 0
497		}
498	
499		total := 0
500		for _, msg := range req.Messages {
501			if len(msg.Content) == 0 {
502				continue
503			}
504			var s string
505			if err := json.Unmarshal(msg.Content, &s); err == nil {
506				total += len(s)
507				continue
508			}
509			var parts []struct {
510				Text string `json:"text"`
511			}
512			if err := json.Unmarshal(msg.Content, &parts); err == nil {
513				for _, p := range parts {
514					total += len(p.Text)
515				}
516			}
517		}
518	
519		if len(req.Input) > 0 {
520			var s string
521			if err := json.Unmarshal(req.Input, &s); err == nil {
522				total += len(s)
523			} else {
524				var arr []string
525				if err := json.Unmarshal(req.Input, &arr); err == nil {
526					for _, s := range arr {
527						total += len(s)
528					}
529				}
530			}
531		}
532	
533		return total / 4
534	}
