536	// rewriteContextLengthError inspects non-2xx upstream responses for a
537	// context_length_exceeded error code and rewrites the status to 400 to match
538	// the OpenAI API standard. llama-server returns these as 500.
539	func rewriteContextLengthError(resp *http.Response) error {
540		if resp.StatusCode >= 200 && resp.StatusCode < 300 {
541			return nil
542		}
543	
544		body, err := io.ReadAll(resp.Body)
545		resp.Body.Close()
546		if err != nil {
547			resp.Body = io.NopCloser(bytes.NewReader(nil))
548			return nil
549		}
550	
551		var envelope struct {
552			Error struct {
553				Code string `json:"code"`
554			} `json:"error"`
555		}
556		if json.Unmarshal(body, &envelope) == nil && envelope.Error.Code == "context_length_exceeded" {
557			resp.StatusCode = http.StatusBadRequest
558			resp.Status = http.StatusText(http.StatusBadRequest)
559		}
560	
561		resp.Body = io.NopCloser(bytes.NewReader(body))
562		return nil
563	}
