565	const hfCacheTTL = 30 * time.Second
566	
567	// scanHFCache returns cached model IDs (org/repo:QUANT) for all GGUF files
568	// found in the HuggingFace hub cache. Results are cached for 30s to avoid
569	// repeated filesystem I/O on /v1/models calls.
570	func (g *Gateway) scanHFCache() []string {
571		if g.hfCacheDir == "" {
572			return nil
573		}
574		if ids, ok := g.hfCache.get(hfCacheTTL); ok {
575			return ids
576		}
577	
578		entries, err := os.ReadDir(g.hfCacheDir)
579		if err != nil {
580			return nil
581		}
582	
583		var models []string
584		for _, entry := range entries {
585			name := entry.Name()
586			if !entry.IsDir() || !strings.HasPrefix(name, "models--") {
587				continue
588			}
589			// models--org--repo → org/repo
590			parts := strings.SplitN(name, "--", 3)
591			if len(parts) != 3 {
592				continue
593			}
594			repo := parts[1] + "/" + parts[2]
595	
596			// Walk snapshots for .gguf files.
597			snapshotsDir := filepath.Join(g.hfCacheDir, name, "snapshots")
598			snapshots, err := os.ReadDir(snapshotsDir)
599			if err != nil {
600				continue
601			}
602			seen := make(map[string]bool)
603			for _, snap := range snapshots {
604				if !snap.IsDir() {
605					continue
606				}
607				ggufs, err := filepath.Glob(filepath.Join(snapshotsDir, snap.Name(), "*.gguf"))
608				if err != nil {
609					continue
610				}
611				for _, path := range ggufs {
612					base := strings.TrimSuffix(filepath.Base(path), ".gguf")
613					// Skip auxiliary files (e.g. mmproj-BF16.gguf).
614					if strings.HasPrefix(base, "mmproj") {
615						continue
616					}
617					// Extract quant: look for Q prefix after the last dash-or-dot, but handle
618					// compound quants like Q5_K_M. The pattern is: model-name[-size]Q<num>[_<variant>]
619					// e.g. "Qwen3-4B-Q8_0" → "Q8_0", "Qwen3-4B-Q5_K_M" → "Q5_K_M"
620					quant := extractQuant(base)
621					if quant == "" {
622						continue
623					}
624					id := repo + ":" + quant
625					if !seen[id] {
626						seen[id] = true
627						models = append(models, id)
628					}
629				}
630			}
631		}
632		g.hfCache.set(models, hfCacheTTL)
633		return models
634	}
635	
636	// extractQuant extracts the quantization suffix from a GGUF filename.
637	// Handles patterns like "Qwen3-4B-Q8_0", "Qwen3-4B-Q5_K_M", "Phi-4-mini-instruct.Q8_0".
638	// Returns empty string if no valid quant is found.
639	func extractQuant(base string) string {
640		// Find last Q<num> and stop at -XB boundary (e.g., -4B, -8B)
641		for i := len(base) - 1; i >= 0; i-- {
642			if i > 0 && base[i] == 'B' && base[i-1] >= '0' && base[i-1] <= '9' {
643				break
644			}
645			if i+1 < len(base) && base[i] == 'Q' && base[i+1] >= '0' && base[i+1] <= '9' {
646				return base[i:]
647			}
648		}
649		return ""
650	}
651	
652	// pathPriority maps a request path to a queue priority tier.
653	func pathPriority(path string) queue.Priority {
654		switch path {
655		case "/v1/completions":
656			return queue.PriorityMedium
657		case "/v1/embeddings", "/v1/rerank":
658			return queue.PriorityLow
659		default:
660			return queue.PriorityHigh
661		}
662	}
663	
664	// writeError writes an OpenAI-format JSON error response.
665	func writeError(w http.ResponseWriter, status int, errType, message, code string) {
666		w.Header().Set("Content-Type", "application/json")
667		w.WriteHeader(status)
668		json.NewEncoder(w).Encode(map[string]any{ //nolint:errcheck
669			"error": map[string]any{
670				"message": message,
671				"type":    errType,
672				"code":    code,
673			},
674		})
675	}
676

