438	func TestEstimateTokens(t *testing.T) {
439		tests := []struct {
440			name string
441			body string
442			want int
443		}{
444			{
445				name: "chat single string content",
446				body: `{"messages":[{"role":"user","content":"` + strings.Repeat("a", 400) + `"}]}`,
447				want: 100, // 400 chars / 4
448			},
449			{
450				name: "chat array content",
451				body: `{"messages":[{"role":"user","content":[{"type":"text","text":"` + strings.Repeat("b", 200) + `"}]}]}`,
452				want: 50, // 200 chars / 4
453			},
454			{
455				name: "embeddings string input",
456				body: `{"model":"embed","input":"` + strings.Repeat("c", 80) + `"}`,
457				want: 20, // 80 chars / 4
458			},
459			{
460				name: "embeddings array input",
461				body: `{"model":"embed","input":["` + strings.Repeat("d", 40) + `","` + strings.Repeat("e", 40) + `"]}`,
462				want: 20, // 80 chars / 4
463			},
464			{
465				name: "invalid json",
466				body: `not json`,
467				want: 0,
468			},
469			{
470				name: "empty messages",
471				body: `{"messages":[]}`,
472				want: 0,
473			},
474		}
475		for _, tc := range tests {
476			t.Run(tc.name, func(t *testing.T) {
477				if got := estimateTokens([]byte(tc.body)); got != tc.want {
478					t.Errorf("estimateTokens = %d, want %d", got, tc.want)
479				}
480			})
481		}
482	}
