390	// TestLoadOrGet_Coalescing verifies that 10 concurrent requests for the same
391	// unloaded model coalesce to a single process start.
392	func TestLoadOrGet_Coalescing(t *testing.T) {
393		cfg := &config.Config{
394			Models:    map[string]config.ModelParams{"org/model-a": {Slots: 1}},
395			MaxModels: 1,
396		}
397		m := New(cfg, slog.Default())
398		// 200 ms startup delay to ensure all goroutines arrive before healthy.
399		m.cmdBuilder = testCmdBuilderWithDelay(200)
400	
401		ctx, cancel := context.WithCancel(context.Background())
402		defer cancel()
403		if err := m.Start(ctx); err != nil {
404			t.Fatalf("Start: %v", err)
405		}
406	
407		params := config.ModelParams{Slots: 1}
408		const n = 10
409		addrs := make([]string, n)
410		var wg sync.WaitGroup
411		wg.Add(n)
412		for i := range n {
413			go func(i int) {
414				defer wg.Done()
415				addr, release, err := loadOrGetWait(ctx, m, "org/model-a", params)
416				if err != nil {
417					t.Errorf("goroutine %d: LoadOrGet error: %v", i, err)
418					return
419				}
420				defer release()
421				addrs[i] = addr
422			}(i)
423		}
424		wg.Wait()
425	
426		// All goroutines must have gotten a non-empty addr.
427		first := addrs[0]
428		if first == "" {
429			t.Fatal("got empty addr")
430		}
431		for i, a := range addrs {
432			if a != first {
433				t.Errorf("goroutine %d: got addr %q, want %q (coalescing failed)", i, a, first)
434			}
435		}
436	
437		// Only one process should have been started.
438		if len(m.RunningModels()) != 1 {
439			t.Errorf("RunningModels: expected 1, got %d", len(m.RunningModels()))
440		}
441	}
