545	// TestLoadOrGet_ContextCancellation verifies that cancelling the requesting
546	// context does not abort the model load. A second request for the same model
547	// (with a valid context) should join the in-progress load.
548	func TestLoadOrGet_ContextCancellation(t *testing.T) {
549		cfg := &config.Config{
550			Models:    map[string]config.ModelParams{"org/model-a": {Slots: 1}},
551			MaxModels: 1,
552		}
553		m := New(cfg, slog.Default())
554		// 400 ms delay so we can cancel the first request mid-load.
555		m.cmdBuilder = testCmdBuilderWithDelay(400)
556	
557		bgCtx, cancel := context.WithCancel(context.Background())
558		defer cancel()
559		if err := m.Start(bgCtx); err != nil {
560			t.Fatalf("Start: %v", err)
561		}
562	
563		params := config.ModelParams{Slots: 1}
564	
565		// First request: cancel the context almost immediately.
