// TestLoadOrGet_Drain verifies drain behavior: once a model is in stateUnloading,
// new requests fail immediately; drainAndCancel waits for the inflight counter
// to reach zero (or the timeout) before sending SIGTERM.
func TestLoadOrGet_Drain(t *testing.T) {
	cfg := &config.Config{
		Models: map[string]config.ModelParams{
			"org/model-a": {Slots: 1},
			"org/model-b": {Slots: 1},
		},
		Warmup:    []string{"org/model-a"},
		MaxModels: 1,
	}
	m := newTestManager(cfg)
	m.drainTimeout = 500 * time.Millisecond

	bgCtx, cancel := context.WithCancel(context.Background())
	defer cancel()
	if err := m.Start(bgCtx); err != nil {
		t.Fatalf("Start: %v", err)
	}
	waitLoadedModel(t, m, "org/model-a", 10*time.Second)

	// Acquire then release model-a — it is now idle (inflight=0, evictable).
	_, releaseA, err := loadOrGetWait(bgCtx, m, "org/model-a", cfg.Models["org/model-a"])
	if err != nil {
		t.Fatalf("LoadOrGet model-a: %v", err)
	}
	releaseA()

	// Request model-b: evicts idle model-a and loads model-b.
	_, releaseB, err := loadOrGetWait(bgCtx, m, "org/model-b", cfg.Models["org/model-b"])
	if err != nil {
		t.Fatalf("LoadOrGet model-b (after eviction): %v", err)
	}
	releaseB()

	if m.Loaded("org/model-a") {
		t.Error("model-a should have been evicted")
	}
	if !m.Loaded("org/model-b") {
		t.Error("model-b should be loaded after eviction")
	}

	// Inject a synthetic proc in stateUnloading to verify that new requests
	// to a draining model are rejected without waiting.
	m.mu.Lock()
	synth := &procState{
		modelName: "org/draining",
		state:     stateUnloading,
		ready:     make(chan struct{}),
		cancel:    func() {},
	}
	m.procs["org/draining"] = synth
	m.mu.Unlock()

	tick := m.LoadOrGet("org/draining", config.ModelParams{})
	select {
	case _, ok := <-tick.Ready():
		if ok {
			t.Error("expected failure for unloading model, got address")
			tick.Release()
		}
	case <-time.After(200 * time.Millisecond):
		t.Error("ticket for draining model should fail immediately")
	}
	if tick.Err() == nil {
		t.Error("expected non-nil error for unloading model")
	}

	// Verify drainAndCancel respects the timeout: create a proc with inflight=1
	// and confirm cancel() is called after drainTimeout.
	ps2 := &procState{modelName: "org/timeout-test", cancel: func() {}}
	ps2.inflight.Add(1)
	start := time.Now()
	m.drainTimeout = 100 * time.Millisecond
	m.drainAndCancel(ps2)
	elapsed := time.Since(start)
	if elapsed < 90*time.Millisecond {
		t.Errorf("drainAndCancel returned in %v; expected to wait ~100ms for timeout", elapsed)
	}
}

// TestLoadOrGet_CascadingVRAMEviction verifies that when VRAM is insufficient
// for a new model, the minimum set of LRU idle models is evicted to make room.
// Models A and B are loaded without a VRAM tracker. Then a tracker is attached
// with a mock backend that reports only 2 GiB free, less than model-c's 3 GiB
// estimate. The cascading eviction must select model-a (LRU) and leave model-b.
func TestLoadOrGet_CascadingVRAMEviction(t *testing.T) {
	const (
		totalVRAM = 8 << 30 // 8 GiB total
		modelEst  = 3 << 30 // 3 GiB per model
		// mock backend reports 6 GiB used → 2 GiB free (not enough for model-c)
		mockUsed = 6 << 30
	)

	cfg := &config.Config{
		Models: map[string]config.ModelParams{
			"org/model-a": {Slots: 1},
			"org/model-b": {Slots: 1},
			"org/model-c": {Slots: 1},
		},
		MaxModels: 10, // no count-based limit; only VRAM drives eviction
	}

	m := newTestManager(cfg)

	bgCtx, cancel := context.WithCancel(context.Background())
	defer cancel()
	if err := m.Start(bgCtx); err != nil {
		t.Fatalf("Start: %v", err)
	}

	// Load model-a first (becomes LRU candidate) — no tracker yet.
	_, releaseA, err := loadOrGetWait(bgCtx, m, "org/model-a", cfg.Models["org/model-a"])
	if err != nil {
		t.Fatalf("LoadOrGet model-a: %v", err)
	}
	releaseA()

	// Load model-b (more recently used) — still no tracker.
	_, releaseB, err := loadOrGetWait(bgCtx, m, "org/model-b", cfg.Models["org/model-b"])
	if err != nil {
		t.Fatalf("LoadOrGet model-b: %v", err)
	}
	releaseB()

	// Now attach a VRAM tracker. The mock backend reports 6 GiB used, leaving
	// only 2 GiB free — insufficient for model-c (3 GiB estimate).
	backend := &mockVRAMBackend{total: totalVRAM, used: mockUsed}
	tracker := vram.New(backend, nil)
	tracker.Discover()
	tracker.SetEstimate("org/model-a", modelEst)
	tracker.SetEstimate("org/model-b", modelEst)
	tracker.SetEstimate("org/model-c", modelEst)
	m.SetVRAMTracker(tracker)

	// Request model-c: 3 GiB needed, only 2 GiB free → must evict model-a (LRU).
	_, releaseC, err := loadOrGetWait(bgCtx, m, "org/model-c", cfg.Models["org/model-c"])
	if err != nil {
		t.Fatalf("LoadOrGet model-c: %v", err)
	}
	releaseC()

	if m.Loaded("org/model-a") {
		t.Error("model-a should have been evicted (LRU)")
	}
	if !m.Loaded("org/model-b") {
		t.Error("model-b should still be loaded (more recently used)")
	}
	if !m.Loaded("org/model-c") {
		t.Error("model-c should be loaded")
	}
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

// waitLoadedModel polls until the named model is healthy or the deadline passes.
func waitLoadedModel(t *testing.T, m *Manager, name string, timeout time.Duration) {
	t.Helper()
	deadline := time.Now().Add(timeout)
	for time.Now().Before(deadline) {
		if m.Loaded(name) {
			return
		}
		time.Sleep(100 * time.Millisecond)
	}
	t.Fatalf("model %q did not become healthy within %v", name, timeout)
}

package queue

import (
	"context"
	"errors"
	"sync"
	"sync/atomic"
	"time"
)

// Priority determines the time budget for a queued request.
type Priority int

const (
	PriorityHigh   Priority = 0 // chat completions: 30s budget
	PriorityMedium Priority = 1 // completions: 15s budget
	PriorityLow    Priority = 2 // embeddings/rerank: 5s budget
)

var defaultBudgets = [3]time.Duration{
	30 * time.Second,
	15 * time.Second,
	5 * time.Second,
}

var (
	// ErrQueueFull is returned when the global depth cap is exceeded.
	ErrQueueFull = errors.New("queue at capacity")
	// ErrModelEvicted is returned when the model is evicted while the ticket is waiting.
	ErrModelEvicted = errors.New("model evicted")
)

// LoadFunc loads a model and returns its backend address and a release function.
// The release function must be called when the proxied request completes.
type LoadFunc func(ctx context.Context, model string) (addr string, release func(), err error)

// Ticket represents a queued request. Returned immediately by Enqueue.
type Ticket struct {
	ready chan string
	mu    sync.Mutex
	err   error
	rel   func()
	once  sync.Once
}

// Ready returns a channel that receives the backend address on success,
// or is closed without a value on failure. Call Err() to inspect the cause.
func (t *Ticket) Ready() <-chan string {
	return t.ready
}

// Err returns the failure cause. Must be called after Ready() closes or is drained.
func (t *Ticket) Err() error {
	t.mu.Lock()
	defer t.mu.Unlock()
	return t.err
}

// Release decrements the in-flight counter. Must be called exactly once after the request completes.
func (t *Ticket) Release() {
	t.once.Do(func() {
		t.mu.Lock()
		rel := t.rel
		t.mu.Unlock()
		if rel != nil {
			rel()
		}
	})
}

func (t *Ticket) succeed(addr string, rel func()) {
	t.mu.Lock()
	t.rel = rel
	t.mu.Unlock()
	t.ready <- addr
}

func (t *Ticket) fail(err error) {
	t.mu.Lock()
	t.err = err
	t.mu.Unlock()
	close(t.ready)
}

// modelQueue serializes initial loading for a single model.
// Concurrent callers coalesce: the first (primary) calls the loader; subsequent callers
// wait for the primary to finish, then call the loader themselves (which returns immediately
// since the model is already loaded at that point).
type modelQueue struct {
	mu          sync.Mutex
	loading     bool
	loadDone    chan struct{}
	evictCtx    context.Context
	evictCancel context.CancelFunc
}

func (mq *modelQueue) load(ctx context.Context, loader LoadFunc, model string) (string, func(), error) {
	mq.mu.Lock()
	if mq.loading {
		done := mq.loadDone
		mq.mu.Unlock()
		select {
		case <-done:
		case <-ctx.Done():
			return "", nil, ctx.Err()
		}
		// Primary finished. Model is now loaded; this call returns immediately.
		return loader(ctx, model)
	}
	// This goroutine is the primary loader.
	mq.loading = true
	done := make(chan struct{})
	mq.loadDone = done
	mq.mu.Unlock()

	addr, rel, err := loader(ctx, model)

	mq.mu.Lock()
	mq.loading = false
	mq.mu.Unlock()
	close(done)

	return addr, rel, err
}

// Queue manages per-model request queuing with time-bounded priority budgets.
type Queue struct {
	mu       sync.Mutex
	models   map[string]*modelQueue
	depth    atomic.Int64
	maxDepth int64
	loader   LoadFunc
	budgets  [3]time.Duration
}

// New creates a Queue with the given depth cap and loader function.
func New(maxDepth int, loader LoadFunc) *Queue {
	return &Queue{
		models:   make(map[string]*modelQueue),
		maxDepth: int64(maxDepth),
		loader:   loader,
		budgets:  defaultBudgets,
	}
}

// Enqueue registers a request for the given model at the specified priority.
// Returns a Ticket immediately; the caller waits on ticket.Ready() for the backend address.
func (q *Queue) Enqueue(model string, prio Priority, reqCtx context.Context) *Ticket {
	if q.depth.Add(1) > q.maxDepth {
		q.depth.Add(-1)
		t := &Ticket{ready: make(chan string, 1)}
		t.fail(ErrQueueFull)
		return t
	}

	q.mu.Lock()
	mq, ok := q.models[model]
	if !ok {
		evictCtx, evictCancel := context.WithCancel(context.Background())
		mq = &modelQueue{
			evictCtx:    evictCtx,
			evictCancel: evictCancel,
		}
		q.models[model] = mq
	}
	q.mu.Unlock()

	t := &Ticket{ready: make(chan string, 1)}

	go func() {
		defer q.depth.Add(-1)

		// Combined context: cancelled by request cancellation or the priority budget.
		ctx, cancel := context.WithTimeout(reqCtx, q.budgets[prio])
		defer cancel()

		// Also watch for model eviction; cancel the load context if evicted.
		go func() {
			select {
			case <-mq.evictCtx.Done():
				cancel()
			case <-ctx.Done():
			}
		}()

		addr, rel, err := mq.load(ctx, q.loader, model)
		if err != nil {
			select {
			case <-mq.evictCtx.Done():
				t.fail(ErrModelEvicted)
			default:
				t.fail(err)
			}
			return
		}

		// Load succeeded, but eviction may have raced. Check before serving.
		select {
		case <-mq.evictCtx.Done():
			if rel != nil {
				rel()
			}
			t.fail(ErrModelEvicted)
			return
		default:
		}

		t.succeed(addr, rel)
	}()

	return t
}

// CancelModel cancels all tickets for the given model with ErrModelEvicted.
// Call this when a model is being evicted by the process manager.
func (q *Queue) CancelModel(model string) {
	q.mu.Lock()
	mq, ok := q.models[model]
	if ok {
		delete(q.models, model)
	}
	q.mu.Unlock()
	if ok {
		mq.evictCancel()
	}
}

