	_, releaseA, err := loadOrGetWait(bgCtx, m, "org/model-a", params)
	if err != nil {
		t.Fatalf("LoadOrGet model-a: %v", err)
	}
	_, releaseB, err := loadOrGetWait(bgCtx, m, "org/model-b", params)
