	// New config: same model, different params.
	newCfg := &config.Config{
		Models:    map[string]config.ModelParams{"org/model-a": {Slots: 2}},
		Warmup:    []string{"org/model-a"},
		MaxModels: 1,
	}
	m.Reload(newCfg)

	// Model should restart and become healthy again.
