	}
	addrAfter, ok := m.Addr("org/model-a")
	if !ok {
		t.Fatal("Addr: expected ok=true after Reload")
	}
	if addrBefore != addrAfter {
		t.Errorf("addr changed after no-op Reload: %q → %q (model was restarted unexpectedly)", addrBefore, addrAfter)
	}
}

