func TestLaunch_OOMScoreAdj(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	m := New(&config.Config{}, slog.Default())
	m.SetCmdBuilder(testCmdBuilder)

