			want: 20, // 80 chars / 4
		},
		{
			name: "embeddings array input",
			body: `{"model":"embed","input":["` + strings.Repeat("d", 40) + `","` + strings.Repeat("e", 40) + `"]}`,
			want: 20, // 80 chars / 4
		},
		{
			name: "invalid json",
			body: `not json`,
			want: 0,
		},
		{
			name: "empty messages",
			body: `{"messages":[]}`,
			want: 0,
		},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			if got := estimateTokens([]byte(tc.body)); got != tc.want {
