	backend := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		w.Write([]byte(`{"choices":[]}`)) //nolint:errcheck
	}))
	defer backend.Close()

	cfg := &config.Config{
		Listen: ":0",
		Models: map[string]config.ModelParams{
			"org/a": {Slots: 1},
			"org/b": {Slots: 1},
			"org/c": {Slots: 1},
		},
		Warmup:    []string{"org/a", "org/b", "org/c"},
		MaxModels: 3,
	}
	mgr := &mockManager{
		addrs:  map[string]string{"org/a": backend.URL, "org/b": backend.URL, "org/c": backend.URL},
		loaded: map[string]bool{"org/a": true, "org/b": true, "org/c": true},
		loadOrGetFn: func(name string) (string, func(), error) {
			mu.Lock()
			loaded = append(loaded, name)
			mu.Unlock()
			return backend.URL, func() {}, nil
		},
	}
	g := newGateway(cfg, mgr, nil, nil, nil, slog.Default())
	g.warmupInterval = time.Millisecond

	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	g.Warmup(ctx)

	mu.Lock()
	defer mu.Unlock()
	if len(loaded) != 3 {
		t.Fatalf("expected 3 models loaded, got %d: %v", len(loaded), loaded)
	}
	// Order must match Warmup slice order.
	want := []string{"org/a", "org/b", "org/c"}
	for i, name := range want {
		if loaded[i] != name {
			t.Errorf("position %d: got %q, want %q", i, loaded[i], name)
		}
	}
}

func TestGateway_Models_WithDiscovery(t *testing.T) {
	discoverySrv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		json.NewEncoder(w).Encode(map[string]any{ //nolint:errcheck
			"data": []map[string]string{
				{"id": "discovered-model", "owned_by": "some-org"},
			},
		})
	}))
	defer discoverySrv.Close()

	cfg := &config.Config{
		Listen:    ":0",
		Models:    map[string]config.ModelParams{},
		MaxModels: 1,
	}
	discovery := monitor.NewModelDiscovery([]monitor.ProviderEndpoint{{
		Name: "prov", BaseURL: discoverySrv.URL, APIKey: "key",
	}}, slog.Default())
	discovery.Start()
	defer discovery.Stop()

	g := newGateway(cfg, &mockManager{}, nil, nil, discovery, slog.Default())

	w := httptest.NewRecorder()
	g.handleModels(w, httptest.NewRequest(http.MethodGet, "/v1/models", nil))

	var resp struct {
		Data []struct {
			ID       string `json:"id"`
			Type     string `json:"type"`
			Status   string `json:"status"`
			Provider string `json:"provider"`
		} `json:"data"`
	}
	if err := json.NewDecoder(w.Body).Decode(&resp); err != nil {
		t.Fatalf("decode: %v", err)
	}

	found := false
	for _, m := range resp.Data {
		if m.ID == "discovered-model" {
			found = true
			if m.Type != "remote" {
				t.Errorf("discovered model type = %q, want remote", m.Type)
			}
			if m.Provider != "prov" {
				t.Errorf("provider = %q, want %q", m.Provider, "prov")
			}
			if m.Status != "available" {
				t.Errorf("status = %q, want %q", m.Status, "available")
			}
		}
	}
	if !found {
		t.Error("discovered-model not in /v1/models response")
	}
}

